# -*- coding: utf-8 -*-
"""Erzeugt die HTML-Fassung der Rekonstruktion 2025 inkl. eingearbeiteter Prüferkorrekturen K1-K16."""
import re, html, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
MD = open(os.path.join(HERE, 'final.md'), encoding='utf-8').read()
CSS = open(os.path.join(HERE, 'style.css'), encoding='utf-8').read()
OUT = r'C:/Users/SALEADMIN/Desktop/Datenrekonstruktion/Ausgabe/Fahrtenbuch_Rekonstruktion_2025_Kovacevic.html'

def de(x, d=1):
    s = f"{x:,.{d}f}"
    return s.replace(',', 'X').replace('.', ',').replace('X', '.')

def num(s):
    s = s.replace('*', '').strip()
    if not re.fullmatch(r'-?[\d\.]+(,\d+)?', s):
        return None
    return float(s.replace('.', '').replace(',', '.'))

# ---------------------------------------------------------------- Abschnitte aus final.md
lines = MD.split('\n')
sec = {}
cur = 'PRE'; sec[cur] = []
for ln in lines:
    m = re.match(r'^(#{2,3}) (.*)$', ln)
    if m:
        cur = m.group(2).strip(); sec[cur] = []
        continue
    sec[cur].append(ln)
def S(prefix):
    for k in sec:
        if k.startswith(prefix):
            return '\n'.join(sec[k]).strip('\n').replace('\n---\n', '\n').strip()
    raise KeyError(prefix)

# ---------------------------------------------------------------- Textkorrekturen (global)
def textfix(t):
    # K11 Übernachtung nur ABGELEITET
    t = t.replace('belegte Übernachtungen (Frankfurt 08./09.04., Wien 10./11.07.)',
                  'Übernachtungen ABGELEITET (Frankfurt 08./09.04.: Parkbeleg über Nacht; Wien 10./11.07.: Parkhaus + Anker am Folgetag; Hotelrechnung fehlt – Prüferkorrektur K11)')
    t = re.sub(r'Übernachtung(?!en ABGELEITET)(?! ABGELEITET)(?! \(ABGELEITET)', 'Übernachtung (ABGELEITET, K11)', t)
    # K15 Kundenzahlen
    t = t.replace('Buchloe 20, Türkheim 52', 'Buchloe 19–20, Türkheim 50 (korr. K15)')
    t = t.replace('Buchloe (20), Türkheim (52)', 'Buchloe (19–20), Türkheim (50) (korr. K15)')
    # Zufallserwartung
    t = t.replace('ca. 14,8 Treffer', 'ca. 14,7–14,8 Treffer')
    return t

# ---------------------------------------------------------------- Markdown -> HTML
KW = r'(BELEGT|ANGABE|MODELL|ABGELEITET|OFFEN|WIDERSPRUCH|INDIZ)'
CLS = {'BELEGT': 'bel', 'ANGABE': 'ang', 'MODELL': 'mod', 'ABGELEITET': 'abg', 'OFFEN': 'off', 'WIDERSPRUCH': 'wid', 'INDIZ': 'ind'}

def inline(s, badges=False):
    s = html.escape(s, quote=False)
    s = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', s)
    s = re.sub(r'`(.+?)`', r'<code>\1</code>', s)
    if badges:
        s = re.sub(r'(?<![\w>])' + KW + r'(?![\w])', lambda m: f'<span class="b {CLS[m.group(1)]}">{m.group(1)}</span>', s)
        s = s.replace('NICHT vereinbar', '<span class="b wid">NICHT vereinbar</span>')
    s = s.replace('☐ bestätigt ☐ abweichend ☐ privat',
                  '<span class="chk"><label><input type="checkbox"> bestätigt</label><label><input type="checkbox"> abweichend</label><label><input type="checkbox"> privat</label></span>')
    s = s.replace('[[K]]', '<span class="corr">').replace('[[/K]]', '</span>')
    return s

def split_row(ln):
    ln = ln.strip()
    if ln.startswith('|'): ln = ln[1:]
    if ln.endswith('|'): ln = ln[:-1]
    return [c.strip() for c in ln.split('|')]

def table_html(header, rows, srccol=None):
    out = ['<div class="scroll"><table>', '<thead><tr>' + ''.join(f'<th>{inline(h)}</th>' for h in header) + '</tr></thead><tbody>']
    n = len(header)
    for r in rows:
        if len(r) >= 2 and all(c == '' for c in r[1:]) and r[0]:
            out.append(f'<tr class="bu"><td colspan="{n}"><em>{inline(r[0], True)}</em></td></tr>')
            continue
        r = (r + [''] * n)[:n]
        cls = ' class="sum"' if r[0].startswith('**') else ''
        tds = []
        for i, c in enumerate(r):
            hc = header[i].lower()
            k = ''
            if 'quelle' in hc or hc == 'beleg (datei/mail)':
                k = ' class="src"'
            elif num(c) is not None:
                k = ' class="r"'
            tds.append(f'<td{k}>{inline(c, True)}</td>')
        out.append(f'<tr{cls}>' + ''.join(tds) + '</tr>')
    out.append('</tbody></table></div>')
    return '\n'.join(out)

def md(t, hook=None):
    """Kleiner Markdown-Konverter. hook(header, rows) -> (header, rows)"""
    t = textfix(t)
    out = []; L = t.split('\n'); i = 0
    while i < len(L):
        ln = L[i]
        if ln.strip().startswith('|') and i + 1 < len(L) and re.match(r'^\s*\|[\s\-\|:]+\|\s*$', L[i + 1]):
            header = split_row(ln); rows = []; i += 2
            while i < len(L) and L[i].strip().startswith('|'):
                rows.append(split_row(L[i])); i += 1
            if hook: header, rows = hook(header, rows)
            out.append(table_html(header, rows)); continue
        if re.match(r'^\s*[-*] ', ln) or re.match(r'^\s*\d+\. ', ln):
            ordered = bool(re.match(r'^\s*\d+\. ', ln))
            tag = 'ol' if ordered else 'ul'
            items = []
            while i < len(L) and (re.match(r'^\s*[-*] ', L[i]) or re.match(r'^\s*\d+\. ', L[i]) or (L[i].startswith('   ') and L[i].strip())):
                x = L[i]
                if re.match(r'^\s{2,}[-*] ', x) or re.match(r'^\s{2,}\d+\. ', x) or (x.startswith('   ') and not re.match(r'^\s*([-*]|\d+\.) ', x)):
                    sub = re.sub(r'^\s*([-*]|\d+\.) ', '', x).strip()
                    if items: items[-1][1].append(sub)
                else:
                    items.append([re.sub(r'^\s*([-*]|\d+\.) ', '', x), []])
                i += 1
            h = [f'<{tag}>']
            for it, subs in items:
                s = inline(it, True)
                if subs:
                    s += '<ul>' + ''.join(f'<li>{inline(x, True)}</li>' for x in subs) + '</ul>'
                h.append(f'<li>{s}</li>')
            h.append(f'</{tag}>'); out.append(''.join(h)); continue
        if ln.startswith('> '):
            out.append(f'<div class="box blue">{inline(ln[2:], True)}</div>'); i += 1; continue
        if ln.strip() in ('', '---'):
            i += 1; continue
        m = re.match(r'^(#{2,4}) (.*)$', ln)
        if m:
            out.append(f'<h4>{inline(m.group(2))}</h4>'); i += 1; continue
        out.append(f'<p>{inline(ln, True)}</p>'); i += 1
    return '\n'.join(out)

# ---------------------------------------------------------------- Korrektursets
K4 = {'KW01', 'KW17', 'KW32', 'KW33', 'KW34'}          # Ankerlücke / Urlaubsverdacht
K5 = {'KW08', 'KW47', 'KW31'}                          # Lokalverkehr < 15 km/Tag
PROB = {'KW03': 'niedrig [[K]](K2, vorher mittel)[[/K]]', 'KW07': 'niedrig [[K]](K6, vorher mittel)[[/K]]',
        'KW09': 'mittel [[K]](K6, vorher hoch)[[/K]]', 'KW44': 'mittel [[K]](K6, vorher hoch)[[/K]]',
        'KW12': 'niedrig–mittel [[K]](K6, vorher hoch)[[/K]]'}
