def kw_of(c):
    m = re.match(r'^(KW\d\d)$', c.strip()); return m.group(1) if m else None

def hook_weeks(header, rows):
    """Für Tabellen mit erster Spalte KW (8.1, 8.6, 9)."""
    if not header or header[0] != 'KW':
        return header, rows
    h = [x.lower() for x in header]
    def col(*names):
        for n in names:
            for j, x in enumerate(h):
                if x.startswith(n): return j
        return None
    c_status = col('status'); c_erg = col('ergebnis'); c_w = col('wahrsch'); c_anm = col('anmerkung'); c_grund = col('grund')
    if c_grund is not None:   # 8.2
        rows = rows + [
            ['KW08 (17.–23.02.) [[K]]neu K5[[/K]]', 'Nach Abzug KW08 + KW09-Hinweg bleiben 56 km in 11 Tagen (ca. 5 km/Tag) < belegtes Minimum 19–33 km/Tag → WIDERSPRUCH'],
            ['KW31 (28.07.–03.08.) – alternativ KW30 [[K]]neu K5[[/K]]', '22.07.–31.07.: 735 km tragen nur EINE Fahrt mit realistischem Lokalverkehr (Rest bei zwei Fahrten 19 km in 9 Tagen)'],
            ['KW47 (17.–23.11.) [[K]]neu K5[[/K]]', 'Innsbruck 16.11. → Hall 23.11.: 372 km; nach 357,9 bleiben 14 km für 7 Tage → WIDERSPRUCH'],
            ['KW01, KW17, KW32, KW33, KW34 [[K]]neu K4[[/K]]', 'Ankerlücken in Feiertags-/Ferienzeiten (Weihnachten/Neujahr, Ostern 18.–27.04. 2.207 km ohne Kartentankung, 31.07.–24.08. 3.643 km ohne Anker) → nicht prüfbar, Modellfahrt verworfen (kein Auffüllen von Lücken, Regel 5)'],
            ['KW49 [[K]]K8[[/K]]', 'Entweder-oder-Konflikt zweier ANGABEN: Lochau 02.12. (Zeit-WIDERSPRUCH) ODER Ostermiething KW49 – nicht als bloßer Ausschluss der Wochenfahrt zu lesen'],
        ]
        return header, rows
    new = []
    for r in rows:
        r = list(r) + [''] * (len(header) - len(r))
        k = kw_of(r[0])
        if k in K4 or k in K5:
            txt = K4TXT if k in K4 else K5TXT
            if c_status is not None: r[c_status] = txt
            if c_erg is not None: r[c_erg] = txt
            if c_anm is not None: r[c_anm] = ('Modell verworfen (K4) – nur zur Klärung' if k in K4 else 'WIDERSPRUCH (K5) – nur zur Klärung')
            if c_w is not None: r[c_w] = '–'
        if k in PROB and c_w is not None and 'ANGABE' not in r[c_w]:
            r[c_w] = PROB[k]
        if k == 'KW03':
            tgt = c_erg if c_erg is not None else (len(header) - 1)
            if c_anm is None:
                r[-1] += ' [[K]]K2: Wels liegt ca. 40 km vom Vermietersitz Gmunden – Fahrzeugtausch als Alternativerklärung (INDIZ).[[/K]]'
        if k == 'KW04' and c_erg is not None:
            r[c_erg] = 'nicht angesetzt [[K]](K1: nun rechnerisch prüfbar – 20.01. Wels km 10 → 24.01. Hall km 1.456 = 1.446 km; Überstellungs-/Fahrzeugwechselwoche, keine Modellfahrt eingesetzt)[[/K]]'
        if k == 'KW49' and c_erg is not None:
            r[c_erg] += ' [[K]]K8: Entweder-oder-Konflikt mit Lochau-ANGABE 02.12.[[/K]]'
        if k == 'KW07':
            r[-1] = r[-1].replace('Wiesing liegt auf der Route (Umweg 2,9 km), Fr 14:51 passt zu Rückfahrt (Abfahrt Ost. ca. 12:45, ABGELEITET)',
                                  'Wiesing liegt an der A12 und damit auf jeder Fahrt Richtung Osten – kein spezifisches Ostermiething-Indiz [[K]](K6/K12)[[/K]]')
        if k == 'KW35':
            r[-1] = r[-1].replace('= Indiz Rückweg aus Raum Salzburg', '(Privatkarte, ohne km) – Rückweg-Reihenfolge nicht bestimmbar [[K]](K12)[[/K]]')
        new.append(r)
