                    new.append(['20.01.–24.01.', '–', '–', 'Wels → … → Hall, Pfannhausstr.', 'nicht zugeordnete Fahrten – Zweck OFFEN (inkl. Überstellung; Tankung 22.01. Hall 47,88 l, km-Eintrag „4770“ unverwertbar)', '10,0', '1.456', '0', '1.446,0', 'OFFEN', 'km-Differenz (K1)'])
                    continue
                if r[0].startswith('Nach 19.01.2025'):
                    new.append(['Nach 19.01.2025 14:21: Rückgabe GM-718IW – Datum und km OFFEN (Übergabeprotokoll fehlt). [[K]]K1:[[/K]] Überstellung Hall → Vermieter (Raum Gmunden/Wels, ca. 250–280 km, ABGELEITET-Spanne) fehlt in der Kette und ist OFFEN; tatsächlicher Wechsel wahrscheinlich 19./20.01. (ABGELEITET), nicht 17.01.'] + [''] * 10)
                    continue
                if r[0].startswith('Übertrag: km-Stand 01.01.2025'):
