            if k and 'Dienstreise' in zweck and (k in K4 or k in K5):
                kmv = r[7]
                r[3] = '– (Hypothese Hall–Ostermiething verworfen; tatsächliche Strecke unbekannt)'
                if k in K4:
                    r[4] = f'verworfene Modellfahrt {k} (Prüferkorrektur K4: Ankerlücke/Urlaubsverdacht) – km nicht zugeordnet, Zweck OFFEN'
                    r[9] = 'OFFEN'
                else:
                    r[4] = f'verworfene Modellfahrt {k} (Prüferkorrektur K5: Lokalverkehr < 15 km/Tag) – km nicht zugeordnet, Zweck OFFEN'
                    r[9] = 'WIDERSPRUCH / OFFEN'
                r[8] = kmv; r[7] = '0'; r[1] = '–'
            if k == 'KW07' and 'Wiesing' in zweck:
                r[4] = zweck.replace('(Wiesing Fr 14:51 auf der Route)', '[[K]](Wiesing nicht als Rückweg-Indiz verwendet, K12)[[/K]]')
            if k == 'KW35' and 'Walserberg' in zweck:
                r[4] = zweck.replace('(Walserberg Do 28.08. 20:41 = Rückweg-Indiz)', '[[K]](Walserberg 28.08. 20:41 Privatkarte ohne km – Reihenfolge nicht bestimmbar, K12)[[/K]]')
            if r[3].startswith('Hall – A9 Gleinalm Nord') or r[3].startswith('Gleinalm – Salzburg'):
                r[3] = '[verworfen] ' + r[3]
                r[4] = 'Hypothese ausgeschlossen: Rückfahrt Salzburg→Hall (ca. 185 km) passt nicht in die km-Kette (26 km belegt); nur EINE Gleinalm-Maut gebucht [[K]](Prüferkorrektur K9)[[/K]] – km nicht zugeordnet, Zweck OFFEN'
                r[9] = 'WIDERSPRUCH / OFFEN'
            if r[0].startswith('02.12. (Arlberg'):
                r[4] += ' [[K]]– K8: Entweder-oder-Konflikt mit Ostermiething KW49; Zeit kaum fahrbar (K7)[[/K]]'
                r[9] = 'ANGABE / WIDERSPRUCH'
            new.append(r)
        # Kettenprüfung + Summen
        prev = None; sb = sp = 0.0
        for r in new:
            if len(r) < 11 or (all(c == '' for c in r[1:])): continue
            a, b = num(r[5]), num(r[6])
            if a is None or b is None: continue
            if prev is not None and abs(prev - a) > 0.05:
                CHAIN_ISSUES.append((name, r[0], prev, a))
            prev = b
            if r[0].startswith('20.12.2024') or r[0].startswith('20.12.–31.12.2024'):
